const WebSocket = require('ws');
const http = require('http');

// Create HTTP server instance
const server = http.createServer();

// Create WebSocket server instance attached to the HTTP server
const wss = new WebSocket.Server({ server });

// Define rooms data structure
const rooms = {};

// Add 'connection' event listener here
wss.on('connection', (ws) => {
  console.log('New client connected');

  // Define joinRoom function here
  const joinRoom = (roomName) => {
    if (!rooms[roomName]) {
      rooms[roomName] = new Set();
    }
    rooms[roomName].add(ws);
    ws.room = roomName;
    console.log(`Client joined room: ${roomName}`);
  };

  // Define leaveRoom function here
  const leaveRoom = () => {
    if (ws.room && rooms[ws.room]) {
      rooms[ws.room].delete(ws);
      if (rooms[ws.room].size === 0) {
        delete rooms[ws.room];
      }
      console.log(`Client left room: ${ws.room}`);
      ws.room = null;
    }
  };

  // Define broadcastToRoom function here
  const broadcastToRoom = (roomName, message, sender) => {
    if (rooms[roomName]) {
      rooms[roomName].forEach((client) => {
        if (client !== sender && client.readyState === WebSocket.OPEN) {
          client.send(message);
        }
      });
    }
  };

  // Add 'message' event listener here
});

